"""Derive SkyyWardrobe/build_skyywardrobe_0.2.8.py from the SET pin 0.2.7 (build_skyywardrobe_0.2.7.py, GENERATED by
tools/wardrobe_0_2_7_patch.py; 0.2.7 stays untouched) AND SkyyWardrobe/test_skyywardrobe_0.2.8.py from test_skyywardrobe_0.2.7.py.
Edit THIS file, never the generated scripts: python tools/wardrobe_0_2_8_patch.py, then python SkyyWardrobe/build_skyywardrobe_0.2.8.py
(never --deploy from an agent). Test: python SkyyWardrobe/test_skyywardrobe_0.2.8.py
Every anchor is asserted once; at the end every change is undone on a copy and compared with the source (nothing else changed).

0.2.8 (2026-10-17) = round FP1 (Potion Flask + Food Pouch; research/Flask-Pouch-Spec.md 4.3). SkyyCooking 0.1.11 adds two lifelong items
(ids Skyy_Flask_Empty / Skyy_Flask_V_<id> and Skyy_Food_Pouch_Empty / Skyy_Food_Pouch_V_<id>, MaxStack 1, may carry metadata). Spec 4.3:
"SkyyWardrobe (Requip): add both prefixes to swap.keepIds (loadouts never pool or move them) and refuse them in the ITEMS space."
  1. BUILT-IN KEPT PREFIXES: WdCfg.builtinKeep(id) = Skyy_Flask_* / Skyy_Food_Pouch_*; WdCfg.keep(id) = builtinKeep OR the swap.keepIds
     list - so every path that already honours keep() (Equip / planEquip "keeps your ...", Deposit all, auto-store, "Use what I wear",
     the pocket-block picks) leaves both items where they are, and a server owner cannot remove them (swap.keepIds keeps its default
     "Skyy_Menu,Skyy_Vault_*"; NO config migration).
  2. THE ITEMS SPACE REFUSES THEM: WdClass.classify answers "-The Potion Flask and Food Pouch stay with you - they never go into Requip."
     (checked before the keep list and before items.allow, so no setting lets them in); a deposit / pick of one changes nothing.
  No command, no bridge key, no saved-data change. Rollback to 0.2.7: safe (0.2.7 would let a Flask / Pouch into Requip as an item -
  the two items arrive with SkyyCooking 0.1.11, so deploy / roll back together with it).
Classes: WdCfg (+ builtinKeep, keep body), WdClass (classify body).
"""
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
HERE = os.path.join(ROOT, "SkyyWardrobe")
LF = "\n"


class Patch(object):
    def __init__(self, src, dst, tag):
        raw = open(src, "rb").read()
        self.nl = "\r\n" if b"\r\n" in raw else "\n"
        assert self.nl == "\n" or raw.count(b"\r\n") == raw.count(b"\n"), "mixed line endings in " + src
        self.s = raw.decode("utf8").replace("\r\n", "\n")
        self.old = self.s
        self.src, self.dst, self.tag = src, dst, tag
        self.changes = []

    def has(self, t):
        return t in self.s

    def rep(self, old, new):
        n = self.s.count(old)
        assert n == 1, "%s anchor count %d: %s" % (self.tag, n, old[:140])
        assert self.s.count(new) == 0, "%s: the new text already exists: %s" % (self.tag, new[:100])
        self.s = self.s.replace(old, new, 1)
        self.changes.append((new, old))

    def finish(self):
        u = self.s
        for new, old in reversed(self.changes):
            assert u.count(new) == 1, "%s: a change is not unique any more: %s" % (self.tag, new[:100])
            u = u.replace(new, old, 1)
        assert u == self.old, "%s: the generated script differs from the source outside the recorded changes" % self.tag
        compile(self.s, self.dst, "exec")
        open(self.dst, "w", encoding="utf8", newline="").write(self.s.replace(LF, self.nl) if self.nl != LF else self.s)
        print("wrote", os.path.relpath(self.dst, ROOT), "(%d lines; source %d; %d changes, undo-compare OK)" % (self.s.count(LF), self.old.count(LF), len(self.changes)))


# ====================================================================================================================== THE BUILD
P = Patch(os.path.join(HERE, "build_skyywardrobe_0.2.7.py"), os.path.join(HERE, "build_skyywardrobe_0.2.8.py"), "build")
assert P.has('VERSION = "0.2.7"\n') and P.has("WdSalv") and not P.has("builtinKeep"), "the source must be the generated build_skyywardrobe_0.2.7.py"
REG0, SYS0 = P.s.count("registerCommand("), P.s.count("registerSystem(")

P.rep('"""SkyyWardrobe 0.2.7 "Requip" - build script GENERATED by tools/wardrobe_0_2_7_patch.py from build_skyywardrobe_0.2.6.py (edit the patch).\n',
      '"""SkyyWardrobe 0.2.8 "Requip" - build script GENERATED by tools/wardrobe_0_2_8_patch.py from build_skyywardrobe_0.2.7.py (edit the patch).\n'
      '0.2.8 (2026-10-17, round FP1; Flask-Pouch-Spec 4.3; full notes: tools/wardrobe_0_2_8_patch.py): SkyyCooking\'s Potion Flask and Food Pouch\n'
      '(Skyy_Flask_* / Skyy_Food_Pouch_*) are BUILT-IN kept ids (WdCfg.builtinKeep, on top of swap.keepIds - loadouts never pool, move, store\n'
      'or salvage them) and the Items space refuses them. Test: python SkyyWardrobe/test_skyywardrobe_0.2.8.py\n'
      '0.2.7 = GENERATED by tools/wardrobe_0_2_7_patch.py from build_skyywardrobe_0.2.6.py.\n')
P.rep('VERSION = "0.2.7"\n', 'VERSION = "0.2.8"\n')
P.rep('M(cfgc, "public static boolean keep(String id) { return inList(id, keepList()); }")\n',
      '# 0.2.8 (tools/wardrobe_0_2_8_patch.py 1): the Potion Flask + Food Pouch (SkyyCooking 0.1.11, lifelong) - kept whatever swap.keepIds says\n'
      'M(cfgc, "public static boolean builtinKeep(String id) { return id != null && (id.startsWith(\\"Skyy_Flask_\\") || id.startsWith(\\"Skyy_Food_Pouch_\\")); }")\n'
      'M(cfgc, "public static boolean keep(String id) { return builtinKeep(id) || inList(id, keepList()); }")\n')
P.rep('''  if (@PKG@.WdCfg.keep(id)) return "-The SkyWynn Menu item and the vault arrows never go into Requip.";\n''',
      '''  if (@PKG@.WdCfg.builtinKeep(id)) return "-The Potion Flask and Food Pouch stay with you - they never go into Requip.";   // 0.2.8
  if (@PKG@.WdCfg.keep(id)) return "-The SkyWynn Menu item and the vault arrows never go into Requip.";\n''')
assert P.s.count("registerCommand(") == REG0 and P.s.count("registerSystem(") == SYS0, "0.2.8 adds no command / system"
P.finish()

# ====================================================================================================================== THE TEST
T = Patch(os.path.join(HERE, "test_skyywardrobe_0.2.7.py"), os.path.join(HERE, "test_skyywardrobe_0.2.8.py"), "test")
assert T.has('VERSION = "0.2.7"\n') and not T.has("builtinKeep")
T.rep('"""Harness for SkyyWardrobe 0.2.7 (', '''"""Harness for SkyyWardrobe 0.2.8 (tools/wardrobe_0_2_8_patch.py; round FP1: the Potion Flask + Food Pouch are built-in kept ids).
Derived from test_skyywardrobe_0.2.7.py: EVERY 0.2.7 section runs again on the 0.2.8 jar, plus:
  FP  (inside X, after X5) WdCfg.builtinKeep / keep for both prefixes (look-alikes not), still kept with swap.keepIds "-" (the Menu item
      then not); the Items space refuses them (single deposit from storage + hotbar, also with items.allow naming them); Deposit all (with
      deposit.hotbar) leaves them; a loadout that picks Empty / a potion kind for their hotbar slots leaves them where they are on Equip;
      nothing of either prefix ever in the pool; conservation + exactly once
  C   class compare 0.2.7 -> 0.2.8 (--base): no class added; WdCfg + builtinKeep only (other changes are bodies)
The 0.2.7 harness text follows:
Harness for SkyyWardrobe 0.2.7 (''')
T.rep('VERSION = "0.2.7"\n', 'VERSION = "0.2.8"\n')
T.rep('BASE = os.path.abspath(arg("--base", os.path.join(HERE, "SkyyWardrobe-0.2.6.jar")))  # 0.2.7: the class compare (the SET pin)',
      'BASE = os.path.abspath(arg("--base", os.path.join(HERE, "SkyyWardrobe-0.2.7.jar")))  # 0.2.8: the class compare (the SET pin)')
T.rep('SCRATCH = os.path.abspath(arg("--dir", os.path.join(TOOLS, "dev", "scratch", "wd027", "w027")))',
      'SCRATCH = os.path.abspath(arg("--dir", os.path.join(TOOLS, "dev", "scratch", "fp1", "sackswd", "w028")))')
T.rep('''    "Potion_Mana": ("consumable", 25), "Ingredient_Feathers_Blue": ("plain", 25), "Deco_Scroll": ("plain", 1),\n''',
      '''    "Potion_Mana": ("consumable", 25), "Ingredient_Feathers_Blue": ("plain", 25), "Deco_Scroll": ("plain", 1),
    # 0.2.8: SkyyCooking's Potion Flask + Food Pouch (MaxStack 1, usable - without the built-in keep they would be Items) + a look-alike
    "Skyy_Flask_Empty": ("consumable", 1), "Skyy_Flask_V_Potion_Health": ("consumable", 1), "Skyy_Food_Pouch_Empty": ("consumable", 1),
    "Skyy_Food_Pouch_V_Food_Bread": ("consumable", 1), "Skyy_FlaskLike_Test": ("consumable", 1),\n''')
FP_TEST = r'''
        # ============================================================ FP 0.2.8 the Potion Flask + Food Pouch stay with you (built-in keep)
        FLS = ["Skyy_Flask_Empty", "Skyy_Flask_V_Potion_Health", "Skyy_Food_Pouch_Empty", "Skyy_Food_Pouch_V_Food_Bread"]
        K.check(all(bool(Cfg.builtinKeep(x)) and bool(Cfg.keep(x)) for x in FLS) and not bool(Cfg.builtinKeep("Skyy_FlaskLike_Test"))
                and not bool(Cfg.builtinKeep("Skyy_Food_Pouch")) and not bool(Cfg.builtinKeep(None)), "FP builtinKeep / keep = exactly the two prefixes")
        clf = {x: str(Cls.classify(stack(x, 1))) for x in FLS}
        K.check(all(v.startswith("-The Potion Flask and Food Pouch stay with you") for v in clf.values()) and str(Cls.classify(stack("Skyy_FlaskLike_Test", 1))) == "i",
                "FP the Items space refuses the Flask / Pouch (a look-alike usable item is still an Item) (%s)" % clf)
        keep0, allow0 = Cfg.KEEP_IDS, Cfg.ALLOW_IDS
        Cfg.KEEP_IDS = "-"
        Cfg.ALLOW_IDS = "Skyy_Flask_*,Skyy_Food_Pouch_*"
        K.check(all(bool(Cfg.keep(x)) for x in FLS) and not bool(Cfg.keep("Skyy_Menu")) and all(str(Cls.classify(stack(x, 1))).startswith("-The Potion Flask") for x in FLS),
                "FP swap.keepIds '-' + items.allow naming them: still kept and refused (a server owner cannot remove them); the Menu item then is not kept")
        Cfg.KEEP_IDS, Cfg.ALLOW_IDS = keep0, allow0
        Fay = W.player("00000000-0000-0000-0000-0000000000f1", "Fay")
        kF = str(Fay.u)
        setc(Fay.sto, 0, stack(FLS[0], 1))
        setc(Fay.sto, 1, stack(FLS[3], 1))
        setc(Fay.sto, 2, stack("Armor_Iron_Head", 1, gdoc("rare", 7)))
        setc(Fay.sto, 3, stack("Potion_Health", 4))
        setc(Fay.hot, 2, stack(FLS[1], 1))
        setc(Fay.hot, 3, stack(FLS[2], 1))
        baseF, _ = census(Fay)
        rf = [run(Fay, 6, 0, "2:0"), run(Fay, 6, 0, "2:1"), run(Fay, 6, 0, "1:2"), run(Fay, 6, 0, "1:3")]
        K.check(all(x.startswith("-The Potion Flask and Food Pouch stay with you") for x in rf) and getc(Fay.sto, 0) is not None
                and getc(Fay.hot, 3) is not None, "FP a single deposit of each (storage + hotbar) is refused, nothing moves (%s)" % rf)
        Cfg.DEP_HOT = True
        rda = run(Fay, 7)
        Cfg.DEP_HOT = False
        dF = Store.get(kF, Fay.u)
        K.check(rda.startswith("+Deposited 2 stacks") and [str(getc(c_, i_).getItemId()) for c_, i_ in ((Fay.sto, 0), (Fay.sto, 1), (Fay.hot, 2), (Fay.hot, 3))] == [FLS[0], FLS[3], FLS[1], FLS[2]]
                and len(ent_by_id(dF, "Armor_Iron_Head")) == 1 and len(ent_by_id(dF, "Potion_Health")) == 1,
                "FP Deposit all (+ hotbar): the helmet + potions in, the Flask / Pouch stay in their slots (%s)" % rda)
        eidF = lambda iid: str(ent_by_id(Store.get(kF, Fay.u), iid)[0].eid)
        rp = [run(Fay, 10, 0, "6|empty"), run(Fay, 10, 0, "7|k:" + eidF("Potion_Health")), run(Fay, 10, 0, "0|e:" + eidF("Armor_Iron_Head"))]
        K.check(all(x.startswith("+") for x in rp), "FP a loadout picks Empty for the Flask's hotbar slot, the potion kind for the Pouch's, the helmet (%s)" % rp)
        gap()
        req = run(Fay, 1, 0)
        cF, dF = census(Fay)
        K.check(str(getc(Fay.hot, 2).getItemId()) == FLS[1] and str(getc(Fay.hot, 3).getItemId()) == FLS[2] and getc(Fay.arm, 0) is not None
                and str(getc(Fay.arm, 0).getItemId()) == "Armor_Iron_Head", "FP Equip: the helmet goes on, the Flask / Pouch stay in hotbar 3 / 4 (Keep wins) (%s)" % req)
        K.check(not any(str(e_.itemId()).startswith("Skyy_Flask_") or str(e_.itemId()).startswith("Skyy_Food_Pouch_") for e_ in list(dF.entries.values())),
                "FP nothing of either prefix is ever in the pool")
        K.check(cF == baseF and not once(Fay, dF), "FP conservation + exactly once")
'''
T.rep('''        K.check(cB == baseB and not once(Bea, dB), "X5 conservation + exactly once")\n''',
      '''        K.check(cB == baseB and not once(Bea, dB), "X5 conservation + exactly once")\n''' + FP_TEST)
T.rep('''    K.check(not removed and added == [PKG + "WdSalv"], "C 0.2.6 -> 0.2.7: WdSalv added, nothing removed (%s / %s)" % (removed, added))''',
      '''    K.check(not removed and added == [], "C 0.2.7 -> 0.2.8: no class added or removed (%s / %s)" % (removed, added))''')
T.rep('''    K.check(real == [], "C (0.2.7) no member of a kept class changed (WdOps ensure / run, WdPage handleDataEvent, the timer, shutdown: bodies only): %s" % real)''',
      '''    K.check(real == ["WdCfg"] and changed["WdCfg"] == {"-": 0, "+": 1} and "builtinKeep(Ljava/lang/String;)Z" in new[PKG + "WdCfg"],
            "C (0.2.8) only WdCfg gains a member (+ builtinKeep); keep / classify: bodies only: %s %s" % (real, changed))''')
T.finish()
